CREATE TABLE dbo.T (Id int NOT NULL CONSTRAINT PK_T PRIMARY KEY, A int NULL)
GO
CREATE TABLE dbo.Audit (Id int NOT NULL)
GO
CREATE TRIGGER dbo.T_Ins ON dbo.T AFTER INSERT AS INSERT dbo.Audit SELECT Id FROM inserted
GO
CREATE TRIGGER dbo.T_Upd ON dbo.T AFTER UPDATE AS SET NOCOUNT ON
GO
DISABLE TRIGGER dbo.T_Upd ON dbo.T
GO
CREATE TRIGGER DdlLog ON DATABASE FOR CREATE_TABLE AS SET NOCOUNT ON
